describe('LessonDetailScreen — loading state', () => {
  it('shows loading indicator while fetching', async () => {
    // Never resolve fetch
    mockFetch.mockReturnValue(new Promise(() => undefined));
    render(<LessonDetailScreen />);
    expect(screen.getByTestId('loading-indicator')).toBeTruthy();
  });

  it('shows loading text', () => {
    mockFetch.mockReturnValue(new Promise(() => undefined));
    render(<LessonDetailScreen />);
    expect(screen.getByText('Loading lesson…')).toBeTruthy();
  });
});

describe('LessonDetailScreen — error state', () => {
  it('shows error text on fetch failure', async () => {
    mockFetch.mockRejectedValueOnce(new Error('Connection refused'));
    render(<LessonDetailScreen />);
    await screen.findByText(/Connection refused/);
  });

  it('shows back button on error', async () => {
    mockFetch.mockRejectedValueOnce(new Error('Oops'));
    render(<LessonDetailScreen />);
    await screen.findByTestId('back-button');
  });

  it('goes back when back button pressed', async () => {
    mockFetch.mockRejectedValueOnce(new Error('Oops'));
    render(<LessonDetailScreen />);
    const btn = await screen.findByTestId('back-button');
    fireEvent.press(btn);
    expect(mockBack).toHaveBeenCalledTimes(1);
  });

  it('shows error on non-ok HTTP response', async () => {
    mockFetch.mockResolvedValueOnce(makeFetchResponse({}, false));
    render(<LessonDetailScreen />);
    await screen.findByText(/HTTP 404/);
  });
});

